// generated by ledger -- do not edit; run `ledger product`
// Types are carried from the tenant's own models. A model Ledger could not import is
// `unknown` here on purpose: a guessed field list is a client that disagrees with the
// engine behind it.

export interface ConfidenceBreakdown {
  retrieval_score?: number;
  legal_match?: number;
  snippet_grounding?: number;
  scope_alignment?: number;
  final?: number;
  explanation?: string;
}

export type DiscoveryTag = "KNOWN" | "NEW";

export type Economy = "SG" | "AU" | "MY" | "CN" | "IN" | "MN" | "TH" | "VN" | "ID" | "KZ" | "LA" | "RU";

/** The core auditable record: a provision mapped to an RDTII indicator. */
export interface EvidenceMapping {
  mapping_id: string;
  run_id: string;
  economy: Economy;
  pillar: number;
  indicator_id: string;
  law_name: string;
  law_number?: string | null;
  last_amended?: string | null;
  article_section: string;
  location_ref?: string | null;
  verbatim_snippet: string;
  source_url: string;
  mapping_rationale: string;
  confidence_score: number;
  discovery_tag: DiscoveryTag;
  coverage?: string | null;
  notes?: string | null;
  language_of_source?: string | null;
  review_status: ReviewStatus;
  raw_score?: number | null;
  impact?: string | null;
  provision_id: string;
  source_pdf_path?: string | null;
  raw_context?: string;
  raw_context_before?: string;
  raw_context_after?: string;
  confidence?: ConfidenceBreakdown;
  ocr?: OCRMetrics;
  model_version?: string;
  retrieval_log?: string[];
  scope_flag?: string | null;
  human_note?: string | null;
}

/** Job envelope defined by Ledger, not by the tenant. The engine entry point is synchronous; this is the handle the API hands back while it runs. */
export interface LedgerJob {
  run_id: string;
  status: "queued" | "running" | "succeeded" | "failed";
  error?: string | null;
}

export interface OCRMetrics {
  used?: boolean;
  provider?: string;
  mean_confidence?: number | null;
  pages?: number;
  chars?: number;
  low_conf_pages?: number[];
  cer?: number | null;
  notes?: string | null;
}

/** Per-document OCR/extraction quality — surfaced at run level so the scanned-PDF proof (provider, pages, measured CER vs reference) is visible even when none of the document's provisions end up in the mapped output. Persisted inside RunMeta. */
export interface OCRReport {
  doc_id: string;
  title: string;
  source_url: string;
  fmt: string;
  ocr_used?: boolean;
  provider?: string;
  pages?: number;
  mean_confidence?: number | null;
  cer?: number | null;
  cer_under_5pct?: boolean | null;
}

/** RFC 9457 problem detail. Every non-2xx response uses this shape. */
export interface Problem {
  type?: string;
  title: string;
  status: number;
  detail?: string | null;
}

export type ReviewStatus = "auto_accepted" | "pending_review" | "quarantined" | "approved" | "rejected" | "corrected";

export interface RunMeta {
  run_id: string;
  economy: Economy;
  pillars: number[];
  started_at: string;
  finished_at?: string | null;
  processing_time_seconds?: number;
  docs_discovered?: number;
  provisions_extracted?: number;
  mappings_produced?: number;
  ocr_provider?: string;
  llm_provider?: string;
  model_version?: string;
  ocr_reports?: OCRReport[];
  notes?: string;
}

export interface RunRequest {
  economy: Economy;
  pillars?: number[];
  use_samples?: boolean;
  top_k?: number;
  ocr_provider?: string | null;
  llm_provider?: string | null;
  llm_model?: string | null;
  llm_api_key?: string | null;
}

export interface RunResult {
  meta: RunMeta;
  mappings?: EvidenceMapping[];
}
